WITH base AS (SELECT * FROM departments WHERE budget >= 3748000), budget_bucket_summary AS (SELECT CASE WHEN budget >= 4051000 THEN 'high' WHEN budget >= 1278000 THEN 'mid' ELSE 'low' END budget_bucket, SUM(budget) total_budget, SUM(CASE WHEN location = 'Singapore' THEN budget ELSE 0 END) singapore_budget FROM base GROUP BY CASE WHEN budget >= 4051000 THEN 'high' WHEN budget >= 1278000 THEN 'mid' ELSE 'low' END) SELECT * FROM budget_bucket_summary WHERE total_budget < 11866000 ORDER BY singapore_budget DESC
